import sys

def to_cents(s: str) -> int:
    if '.' in s:
        whole, frac = s.split('.')
        frac = (frac + '00')[:2]
    else:
        whole, frac = s, '00'
    return int(whole) * 100 + int(frac)

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    idx = 1
    ans = []

    for _ in range(n):
        state = data[idx]
        a = to_cents(data[idx + 1])
        g = to_cents(data[idx + 2])
        idx += 3

        if 10 * a <= 7 * g:
            ans.append(state)

    if ans:
        sys.stdout.write("\n".join(ans) + "\n")
    else:
        sys.stdout.write("*\n")

if __name__ == "__main__":
    main()
